package com.dormrepair.v2.catalog;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import com.dormrepair.v2.identity.*;
import com.dormrepair.v2.platform.api.*;
@Service @ConditionalOnProperty(name="app.v2.enabled",havingValue="true")
public class CatalogService {
 private final CatalogRepository repo;private final RbacIdentity identity;private final SecurityAudit audit;
 public CatalogService(CatalogRepository repo,RbacIdentity identity,SecurityAudit audit){this.repo=repo;this.identity=identity;this.audit=audit;}
 static final Map<String,String> TABLES=Map.of("categories","repair_category","items","repair_item","campuses","campus","buildings","building","floors","building_floor","rooms","room","facility-types","facility_type","facilities","facility");
 String table(String kind){var t=TABLES.get(kind);if(t==null)throw error(404);return t;}
 String domain(String kind){return switch(kind){case "categories","items"->"category";case "facility-types","facilities"->"facility";default->"space";};}
 static ResponseStatusException error(int status){return new ResponseStatusException(HttpStatus.valueOf(status));}
 long id(Object value){if(!(value instanceof String s))throw error(400);return V2Id.parse(s).value();}
 Map<String,Object> require(String table,long id){var row=repo.row(table,id);if(row==null)throw error(404);return row;}
 boolean enabled(Map<String,Object> row){return Boolean.TRUE.equals(row.get("enabled"));}
 boolean categoryEffective(long id){var row=require("repair_category",id);return enabled(row)&&(row.get("parent_id")==null||categoryEffective(((Number)row.get("parent_id")).longValue()));}
 boolean itemEffective(Map<String,Object> item){return enabled(item)&&categoryEffective(((Number)item.get("category_id")).longValue());}
 boolean spaceEffective(String table,long id){var row=require(table,id);if(!enabled(row))return false;return switch(table){case "building"->spaceEffective("campus",((Number)row.get("campus_id")).longValue());case "building_floor"->spaceEffective("building",((Number)row.get("building_id")).longValue());case "room"->spaceEffective("building_floor",((Number)row.get("floor_id")).longValue());default->true;};}
 Map<String,Object> view(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();row.forEach((k,v)->{if(!k.startsWith("qr_token"))out.put(camel(k),v==null?null:(k.equals("id")||k.endsWith("_id"))?v.toString():v instanceof java.sql.Timestamp? v.toString():v);});return out;}
 String camel(String k){var b=new StringBuilder();boolean up=false;for(char c:k.toCharArray()){if(c=='_')up=true;else{b.append(up?Character.toUpperCase(c):c);up=false;}}return b.toString();}
 @Transactional(readOnly=true) public V2Page<Map<String,Object>> list(String kind,int page,int size){identity.require(domain(kind)+":write");String t=table(kind);var request=new V2Page.Request(page,size);var rows=repo.jdbc().queryForList("select * from public."+t+" order by "+(kind.equals("facilities")?"id":"sort_order,id")+" limit ? offset ?",size,request.offset());return new V2Page<>(rows.stream().map(this::view).toList(),page,size,repo.jdbc().queryForObject("select count(*) from public."+t,Long.class));}
 @Transactional(readOnly=true) public Map<String,Object> detail(String kind,long id){identity.require(domain(kind)+":write");var out=view(require(table(kind),id));if(kind.equals("facility-types")){var items=repo.jdbc().queryForList("select i.* from public.repair_item i join public.facility_type_repair_item t on t.item_id=i.id where t.type_id=? order by i.sort_order,i.id",id);out.put("items",items.stream().map(this::view).toList());out.put("itemIds",items.stream().map(i->i.get("id").toString()).toList());}return out;}
 @Transactional public Map<String,Object> save(String kind,Long target,Map<String,Object> input){String t=table(kind);repo.lock();var actor=identity.require(domain(kind)+":write");var values=new LinkedHashMap<String,Object>();var allowed=new LinkedHashSet<String>(List.of("name"));
 if(!kind.equals("facilities")){allowed.addAll(List.of("enabled","sortOrder"));if(!Set.of("floors","rooms").contains(kind))allowed.add("code");}
 switch(kind){case "categories"->allowed.add("parentId");case "items"->allowed.addAll(List.of("categoryId","estimatedMinutes","isQuick"));case "buildings"->allowed.add("campusId");case "floors"->allowed.addAll(List.of("buildingId","floorNo"));case "rooms"->allowed.addAll(List.of("floorId","roomNo","kind"));case "facilities"->allowed.addAll(List.of("assetNo","facilityTypeId","buildingId","floorId","roomId","publicZone","status"));default->{}}
 var accepted=new HashSet<>(allowed);if(target!=null)accepted.add("version");if(!accepted.containsAll(input.keySet()))throw error(400);
 for(var e:input.entrySet()){String k=e.getKey();if(k.equals("version"))continue;Object v=e.getValue();if(k.endsWith("Id")){v=v==null?null:id(v);}else if(k.equals("enabled")||k.equals("isQuick")){if(!(v instanceof Boolean))throw error(400);}else if(Set.of("sortOrder","floorNo","estimatedMinutes").contains(k)){if(!(v instanceof Integer))throw error(400);}else{if(!(v instanceof String s)||s.isBlank()||s.length()>150)throw error(400);v=s.trim();}values.put(k.replaceAll("([A-Z])","_$1").toLowerCase(Locale.ROOT),v);}
 Map<String,Object> merged=new LinkedHashMap<>();int version=0;if(target!=null){merged.putAll(require(t,target));if(!(input.get("version") instanceof Integer n)||n<0)throw error(400);version=n;if(((Number)merged.get("version")).intValue()!=version)throw error(409);}merged.putAll(values);
 if(!merged.containsKey("name"))throw error(400);if(target==null){values.putIfAbsent("enabled",true);values.putIfAbsent("sort_order",0);if(kind.equals("facilities")){values.remove("enabled");values.remove("sort_order");values.putIfAbsent("status","ACTIVE");String token=UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-","");values.put("qr_token",token);values.put("qr_token_hash",hash(token));}merged.putAll(values);}
 if(kind.equals("categories")){if(target==null&&merged.get("parent_id")==null)throw error(409);if(target!=null&&require(t,target).get("parent_id")==null&&(values.containsKey("code")||values.containsKey("name")))throw error(409);if(merged.get("parent_id")!=null)require(t,((Number)merged.get("parent_id")).longValue());}
 if(kind.equals("items")){if(merged.get("category_id")==null||merged.get("estimated_minutes")==null)throw error(400);var category=require("repair_category",((Number)merged.get("category_id")).longValue());if(merged.get("name").equals(category.get("name")))throw error(409);}
 if(kind.equals("facilities")){if(merged.get("facility_type_id")==null||merged.get("building_id")==null)throw error(400);require("facility_type",((Number)merged.get("facility_type_id")).longValue());require("building",((Number)merged.get("building_id")).longValue());}
 long saved=target==null?repo.insert(t,values):target;if(target!=null&&(values.isEmpty()||repo.update(t,target,version,values)!=1))throw error(409);audit.record(actor.user().id(),target==null?"CATALOG_CREATED":"CATALOG_UPDATED",t.toUpperCase(Locale.ROOT),saved,Map.of("fields",values.keySet().stream().filter(k->!k.startsWith("qr_")).toList()));return view(require(t,saved));
 }
 static String hash(String token){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(token.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 @Transactional public Map<String,Object> bind(long type,int version,List<String> itemIds){repo.lock();var actor=identity.require("facility:write");var row=require("facility_type",type);if(((Number)row.get("version")).intValue()!=version)throw error(409);if(itemIds.size()>100||new HashSet<>(itemIds).size()!=itemIds.size())throw error(400);var ids=itemIds.stream().map(this::id).toList();for(long item:ids)require("repair_item",item);repo.jdbc().update("delete from public.facility_type_repair_item where type_id=?",type);for(long item:ids)repo.jdbc().update("insert into public.facility_type_repair_item values (?,?)",type,item);repo.jdbc().update("update public.facility_type set version=version+1 where id=?",type);audit.record(actor.user().id(),"TYPE_ITEMS_UPDATED","FACILITY_TYPE",type,Map.of("itemCount",ids.size()));return Map.of("id",Long.toString(type),"version",version+1,"itemIds",itemIds);}
 static final String CATEGORY_CTE="with recursive valid as(select * from public.repair_category where parent_id is null and enabled union all select c.* from public.repair_category c join valid p on c.parent_id=p.id where c.enabled) ";
 static final String FACILITY_FROM=" from public.facility f join public.facility_type t on t.id=f.facility_type_id join public.building b on b.id=f.building_id join public.campus c on c.id=b.campus_id left join public.building_floor fl on fl.id=f.floor_id left join public.room rm on rm.id=f.room_id where f.status='ACTIVE' and t.enabled and b.enabled and c.enabled and (f.floor_id is null or fl.enabled) and (f.room_id is null or (rm.enabled and rm.kind='PUBLIC'))";
 @Transactional(readOnly=true) public List<Map<String,Object>> select(String kind,Long parent,boolean quick){identity.require(domain(kind)+":read");table(kind);String query;var args=new ArrayList<Object>();
 if(kind.equals("categories")){query=CATEGORY_CTE+"select * from valid where "+(parent==null?"parent_id is null":"parent_id=?");if(parent!=null)args.add(parent);}
 else if(kind.equals("items")){if(parent==null&&!quick)throw error(400);query=CATEGORY_CTE+"select i.* from public.repair_item i join valid c on c.id=i.category_id where i.enabled"+(quick?" and i.is_quick":"")+(parent==null?"":" and i.category_id=?");if(parent!=null)args.add(parent);}
 else {String joins=switch(kind){case "campuses"->" from public.campus x where x.enabled";case "buildings"->" from public.building x join public.campus c on c.id=x.campus_id where x.enabled and c.enabled and x.campus_id=?";case "floors"->" from public.building_floor x join public.building b on b.id=x.building_id join public.campus c on c.id=b.campus_id where x.enabled and b.enabled and c.enabled and x.building_id=?";case "rooms"->" from public.room x join public.building_floor fl on fl.id=x.floor_id join public.building b on b.id=fl.building_id join public.campus c on c.id=b.campus_id where x.enabled and fl.enabled and b.enabled and c.enabled and x.floor_id=?";default->throw error(400);};if(!kind.equals("campuses")){if(parent==null)throw error(400);args.add(parent);}query="select x.*"+joins;}
 query+=" order by sort_order,id limit 101";var rows=repo.jdbc().queryForList(query,args.toArray());if(rows.size()>100)throw error(409);return rows.stream().map(this::view).toList();}
 private List<Map<String,Object>> facilityViews(List<Map<String,Object>> rows){if(rows.isEmpty())return List.of();var types=rows.stream().map(r->((Number)r.get("facility_type_id")).longValue()).distinct().toList();String marks=String.join(",",Collections.nCopies(types.size(),"?"));var items=repo.jdbc().queryForList(CATEGORY_CTE+"select i.*,t.type_id from public.repair_item i join valid c on c.id=i.category_id join public.facility_type_repair_item t on t.item_id=i.id where i.enabled and t.type_id in ("+marks+") order by i.sort_order,i.id",types.toArray());var grouped=new HashMap<Long,List<Map<String,Object>>>();for(var item:items){long type=((Number)item.get("type_id")).longValue();var v=new LinkedHashMap<>(item);v.remove("type_id");grouped.computeIfAbsent(type,k->new ArrayList<>()).add(view(v));}var out=new ArrayList<Map<String,Object>>();for(var row:rows){var m=new LinkedHashMap<String,Object>();m.put("id",row.get("id").toString());m.put("name",row.get("name"));m.put("buildingId",row.get("building_id").toString());m.put("publicZone",row.get("public_zone"));m.put("items",grouped.getOrDefault(((Number)row.get("facility_type_id")).longValue(),List.of()));m.put("canSubmitOrder",false);out.add(m);}return out;}
 @Transactional(readOnly=true) public Map<String,Object> resolve(String token){identity.require("facility:read");if(token==null||!token.matches("[a-f0-9]{64}"))throw error(404);var rows=repo.jdbc().queryForList("select f.*"+FACILITY_FROM+" and f.qr_token_hash=?",hash(token));if(rows.isEmpty())throw error(404);return facilityViews(rows).getFirst();}
 @Transactional(readOnly=true) public V2Page<Map<String,Object>> facilities(int page,int size){identity.require("facility:read");var request=new V2Page.Request(page,size);var rows=repo.jdbc().queryForList("select f.*"+FACILITY_FROM+" order by f.id limit ? offset ?",size,request.offset());long total=repo.jdbc().queryForObject("select count(*)"+FACILITY_FROM,Long.class);return new V2Page<>(facilityViews(rows),page,size,total);}
 @Transactional(readOnly=true) public List<Map<String,Object>> tree(){identity.require("category:read");var rows=repo.jdbc().queryForList("with recursive valid as(select * from public.repair_category where parent_id is null and enabled union all select c.* from public.repair_category c join valid p on c.parent_id=p.id where c.enabled) select * from valid order by sort_order,id limit 1001");if(rows.size()>1000)throw error(409);var mapped=new LinkedHashMap<String,Map<String,Object>>();for(var row:rows){var v=view(row);v.put("children",new ArrayList<Map<String,Object>>());mapped.put(v.get("id").toString(),v);}var roots=new ArrayList<Map<String,Object>>();for(var v:mapped.values()){if(v.get("parentId")==null)roots.add(v);else {var parent=mapped.get(v.get("parentId").toString());if(parent!=null){@SuppressWarnings("unchecked") var children=(List<Map<String,Object>>)parent.get("children");children.add(v);}}}return roots;}
 @Transactional(readOnly=true) public String qr(long id){identity.require("facility:write");return "dormrepair://facility/"+require("facility",id).get("qr_token");}
}
